import 'package:flutter_test/flutter_test.dart';

import 'fake_issuer_client.dart';
import 'fixtures.dart';

void main() {
  testWidgets('shows an empty wallet', (tester) async {
    await tester.pumpWidget(
      const MaterialApp(
        home: Scaffold(body: CredentialList(credentials: [])),
      ),
    );
    expect(find.text('No credentials yet'), findsOneWidget);
  });

  testWidgets('lists held credentials by type and issuer', (tester) async {
    final credential = HeldCredential.fromIssuance(membershipIssuance());
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(body: CredentialList(credentials: [credential])),
      ),
    );
    expect(find.text('MembershipCredential'), findsOneWidget);
    expect(find.text(issuerDid), findsOneWidget);
  });

  testWidgets('requesting a membership adds it to the list', (tester) async {
    final wallet = WalletService(issuer: FakeIssuerClient());
    await tester.pumpWidget(MaterialApp(home: WalletScreen(wallet: wallet)));
    expect(find.text('No credentials yet'), findsOneWidget);

    await tester.tap(find.text('Request membership'));
    await tester.pumpAndSettle();

    expect(find.text('MembershipCredential'), findsOneWidget);
    expect(wallet.heldCredentials(), hasLength(1));
  });

  testWidgets('a failed request shows an error', (tester) async {
    final wallet = WalletService(
      issuer: FakeIssuerClient(subjectOverride: 'did:key:z6MkSomeoneElse'),
    );
    await tester.pumpWidget(MaterialApp(home: WalletScreen(wallet: wallet)));

    await tester.tap(find.text('Request membership'));
    await tester.pumpAndSettle();

    expect(find.textContaining('Could not add credential'), findsOneWidget);
    expect(find.text('No credentials yet'), findsOneWidget);
  });
}
import 'package:credentials_app/credentials_app.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fixtures.dart';

void main() {
  late CredentialStore store;
  setUp(() => store = CredentialStore());

  test('parses an issued credential with its disclosures', () {
    final credential = HeldCredential.fromIssuance(membershipIssuance());
    expect(credential.id, 'urn:uuid:5b1d7c2e-0f7a-4c3e-9d0b-6a2f1e8c4d11');
    expect(credential.issuer, issuerDid);
    expect(credential.holderDid, holderDid);
    expect(credential.type, 'MembershipCredential');
    expect(credential.disclosures.map((d) => d.name), [
      'member',
      'memberId',
      'name',
      'birthDate',
    ]);
    expect(credential.disclosures.first.value, true);
    expect(credential.disclosures.first.salt, 'Qg8wYx1dLr0pVb3kTz7sNw');
  });

  test('saves and finds a credential by id', () {
    final credential = HeldCredential.fromIssuance(membershipIssuance());
    store.save(credential);
    expect(store.byId(credential.id)?.issuer, issuerDid);
    expect(store.byId('urn:uuid:unknown'), isNull);
  });

  test('lists every held credential', () {
    expect(store.all(), isEmpty);
    store.save(HeldCredential.fromIssuance(membershipIssuance()));
    expect(store.all(), hasLength(1));
  });

  test('saving the same id twice keeps one copy', () {
    store.save(HeldCredential.fromIssuance(membershipIssuance()));
    store.save(HeldCredential.fromIssuance(membershipIssuance()));
    expect(store.all(), hasLength(1));
  });

  test('keeps the holder key', () {
    expect(store.holderKey, isNull);
    store.holderKey = HolderKey.fromSeed(holderSeed);
    expect(store.holderKey?.did, holderDid);
  });
}
import 'package:credentials_app/credentials_app.dart';

import 'fixtures.dart';

class FakeIssuerClient implements IssuerClient {
  FakeIssuerClient({this.subjectOverride});

  /// When set, the issued credential names this subject instead of the caller.
  final String? subjectOverride;

  final List<({String holderDid, String credentialType})> calls = [];

  @override
  Future<HeldCredential> issue({
    required String holderDid,
    required String credentialType,
  }) async {
    calls.add((holderDid: holderDid, credentialType: credentialType));
    return HeldCredential.fromIssuance(
      membershipIssuance(subject: subjectOverride ?? holderDid),
    );
  }
}
import 'dart:typed_data';

/// Seed of the holder key the fixture credential was issued to.
final Uint8List holderSeed = Uint8List.fromList(List.filled(32, 7));

const holderDid = 'did:key:z6MkvDqGT54cXesYGvABpF1UapVNwjCqRcafi4Px6Thv5T3Z';

const issuerDid = 'did:web:issuer.members.test';

/// Issuer response for a membership credential, as the issuer service returns it.
Map<String, dynamic> membershipIssuance({String subject = holderDid}) => {
  'credential': {
    '@context': ['https://www.w3.org/ns/credentials/v2'],
    'id': 'urn:uuid:5b1d7c2e-0f7a-4c3e-9d0b-6a2f1e8c4d11',
    'type': ['VerifiableCredential', 'MembershipCredential'],
    'issuer': issuerDid,
    'validFrom': '2026-01-01T00:00:00Z',
    'validUntil': '2027-01-01T00:00:00Z',
    'credentialSubject': {
      'id': subject,
      '_sd': [
        'JVmpmvr8l44m-VjhbllpxsgwyKDSC_EcWIdoCZj1SLs',
        'F8w8nFje9RpZ9F8EJ5jGh6BUWuAXz_umNdTgEBhpl5s',
        '51mkbb932Hakyr67b_toNlii0D2o6nhzAOxig4ii8Jk',
        'REwmh76r9rNH8My4qBGgDd7oG07vsiHQX2Qt-w-b8Qg',
      ],
    },
    'proof': {
      'type': 'DataIntegrityProof',
      'cryptosuite': 'eddsa-jcs-2022',
      'verificationMethod': '$issuerDid#key-1',
      'proofPurpose': 'assertionMethod',
      'proofValue': 'z3FXQjecWufY46yg5abdVZsXqLhxhueuSoZgNSARiKBk9czhSePTFehP8c3PGfb6a22gkfUKKy2Rj2cUk5WBLgmPs',
    },
  },
  'disclosures': [
    {'salt': 'Qg8wYx1dLr0pVb3kTz7sNw', 'name': 'member', 'value': true},
    {'salt': 'bM4rT9cZ2xKq1nVf0hJw8A', 'name': 'memberId', 'value': 'M-20417'},
    {'salt': 'u7EoH3pWq5sLd2yGk9rCzQ', 'name': 'name', 'value': 'Ada Park'},
    {
      'salt': 'X2nR6vBt1fYk8mJq4cLwEg',
      'name': 'birthDate',
      'value': '1990-04-12',
    },
  ],
};

/// A door-scanner request, shaped like an OpenID4VP authorization request.
Map<String, dynamic> doorRequest() => {
  'client_id': 'door-scanner.members.test',
  'nonce': 'n-8f3Kq2xWz0Lb',
  'response_uri': 'https://door-scanner.members.test/presentations',
  'dcql_query': {
    'credentials': [
      {
        'id': 'membership',
        'format': 'ldp_vc',
        'claims': [
          {
            'path': ['credentialSubject', 'member'],
          },
        ],
      },
    ],
  },
};
import 'package:credentials_app/credentials_app.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fixtures.dart';

void main() {
  test('a generated holder key is an Ed25519 did:key', () {
    final key = HolderKey.generate();
    expect(key.did, startsWith('did:key:z6Mk'));
    expect(key.keyId, '${key.did}#${key.did.substring('did:key:'.length)}');
  });

  test('two generated keys have different DIDs', () {
    expect(HolderKey.generate().did, isNot(HolderKey.generate().did));
  });

  test('a key from a fixed seed has a stable DID', () {
    expect(HolderKey.fromSeed(holderSeed).did, holderDid);
  });

  test('the holder key signs with Ed25519', () async {
    final key = HolderKey.fromSeed(holderSeed);
    final data = [1, 2, 3];
    final signature = await key.sign(data);
    expect(signature, hasLength(64));
    expect(await key.verify(data, signature), isTrue);
  });
}
// Smoke test: imports the pinned Affinidi packages `ssi` and `dcql` and
// exercises one offline, non-network call from each — proving the deps are
// real, pinned, and wired up (FM-08). No did:web resolution, no I/O.

import 'package:flutter_test/flutter_test.dart';
import 'package:ssi/ssi.dart';
import 'package:dcql/dcql.dart';

void main() {
  test('generates an Ed25519 key pair via the ssi package', () {
    final (keyPair, privateKeyBytes) = Ed25519KeyPair.generate();
    expect(keyPair.id, isNotEmpty);
    expect(privateKeyBytes, isNotEmpty);
  });

  test('builds a DCQL credential query via the dcql package', () {
    final query = DcqlCredentialQuery(
      credentials: [
        DcqlCredential(id: 'cred1', format: CredentialFormat.jwtVcJson),
      ],
    );
    expect(query.credentials, hasLength(1));
  });
}
import 'package:credentials_app/credentials_app.dart';
import 'package:dcql/dcql.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fake_issuer_client.dart';
import 'fixtures.dart';

void main() {
  test('creates a holder key once and reuses it', () {
    final wallet = WalletService(issuer: FakeIssuerClient());
    final first = wallet.holderKey();
    expect(first.did, startsWith('did:key:'));
    expect(wallet.holderKey().did, first.did);
  });

  test('requests a credential for the holder DID and stores it', () async {
    final client = FakeIssuerClient();
    final wallet = WalletService(
      issuer: client,
      newKey: () => HolderKey.fromSeed(holderSeed),
    );

    final credential = await wallet.requestCredential('MembershipCredential');

    expect(client.calls.single.holderDid, holderDid);
    expect(client.calls.single.credentialType, 'MembershipCredential');
    expect(credential.holderDid, holderDid);
    expect(wallet.heldCredentials().map((c) => c.id), [credential.id]);
  });

  test('refuses a credential issued to someone else', () async {
    final wallet = WalletService(
      issuer: FakeIssuerClient(subjectOverride: 'did:key:z6MkSomeoneElse'),
    );
    await expectLater(
      wallet.requestCredential('MembershipCredential'),
      throwsA(isA<WalletException>()),
    );
    expect(wallet.heldCredentials(), isEmpty);
  });

  test('parses a presentation request', () {
    final request = PresentationRequest.fromJson(doorRequest());
    expect(request.nonce, 'n-8f3Kq2xWz0Lb');
    expect(request.domain, 'door-scanner.members.test');
    expect(
      request.responseUri,
      Uri.parse('https://door-scanner.members.test/presentations'),
    );
    final credential = request.dcqlQuery.credentials.single;
    expect(credential.id, 'membership');
    expect(credential.format, CredentialFormat.ldpVc);
    expect(credential.claims!.single.path, ['credentialSubject', 'member']);
  });

  test('rejects a presentation request without a nonce', () {
    final json = doorRequest()..remove('nonce');
    expect(() => PresentationRequest.fromJson(json), throwsFormatException);
  });
}

